const B = p.B, L = p.L, v = p.v, R = p.R;
const emf = B * L * v, I = emf / R, F = B * I * L, P = emf * I;

const pad = 34;
const yTop = pad + 10, yBot = H - pad - 14;
const xL = pad + 18, xR = W - pad;

// rails
ctx.lineWidth = 2;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(xL, yTop); ctx.lineTo(xR, yTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xL, yBot); ctx.lineTo(xR, yBot); ctx.stroke();

// resistor box on the left end
const bw = 26, bh = 14;
ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.moveTo(xL, yTop); ctx.lineTo(xL, (yTop + yBot) / 2 - bh); ctx.stroke();
ctx.beginPath(); ctx.moveTo(xL, yBot); ctx.lineTo(xL, (yTop + yBot) / 2 + bh); ctx.stroke();
ctx.strokeRect(xL - bw / 2, (yTop + yBot) / 2 - bh, bw, 2 * bh);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("R", xL, (yTop + yBot) / 2 + 4);

// field dots out of the page
ctx.fillStyle = C.faint;
for (let gx = xL + 46; gx < xR - 10; gx += 34) {
  for (let gy = yTop + 20; gy < yBot - 8; gy += 26) {
    ctx.beginPath(); ctx.arc(gx, gy, 2, 0, Math.PI * 2); ctx.fill();
  }
}
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("B out of page", xL + 46, yTop + 12);

// rod position: cycles across the rails
const travel = xR - 26 - (xL + 52);
const per = 4.0;
const rx = xL + 52 + travel * ((t % per) / per);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 4;
ctx.beginPath(); ctx.moveTo(rx, yTop); ctx.lineTo(rx, yBot); ctx.stroke();

// velocity arrow
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
const vy = (yTop + yBot) / 2 - 26;
const av = 34;
ctx.beginPath(); ctx.moveTo(rx, vy); ctx.lineTo(rx + av, vy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(rx + av, vy); ctx.lineTo(rx + av - 6, vy - 4); ctx.lineTo(rx + av - 6, vy + 4); ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("v", rx + av + 4, vy + 4);

// magnetic drag arrow, scaled to the force
ctx.strokeStyle = C.ink;
const aF = Math.min(48, 8 + F * 260);
const fy = (yTop + yBot) / 2 + 26;
ctx.beginPath(); ctx.moveTo(rx, fy); ctx.lineTo(rx - aF, fy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(rx - aF, fy); ctx.lineTo(rx - aF + 6, fy - 4); ctx.lineTo(rx - aF + 6, fy + 4); ctx.closePath();
ctx.fillStyle = C.ink; ctx.fill();
ctx.textAlign = "right";
ctx.fillText("F = BIL", rx - aF - 4, fy + 4);

// current arrows around the loop
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.textAlign = "center";
ctx.fillStyle = C.accent;
ctx.fillText("I", (xL + rx) / 2, yTop - 6);
ctx.fillText("I", (xL + rx) / 2, yBot + 16);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("rod, length L", rx + 6, yBot + 16);

out.note = "emf = BLv = " + emf.toFixed(3) + " V, I = " + I.toFixed(3) + " A, F = " + F.toFixed(4) + " N, P = " + P.toFixed(4) + " W";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

// ---- left panel: charge separation inside the rod ----
const midX = W * 0.46;
const cx = W * 0.20;
const top = 34, bot = H - 46;

ctx.strokeStyle = C.accent;
ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(cx, top); ctx.lineTo(cx, bot); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("+", cx, top - 8);
ctx.fillText("-", cx, bot + 16);
ctx.fillText("rod seen edge-on", cx, H - 12);

// v arrow
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
const my = (top + bot) / 2;
ctx.beginPath(); ctx.moveTo(cx, my); ctx.lineTo(cx + 44, my); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx + 44, my); ctx.lineTo(cx + 37, my - 4); ctx.lineTo(cx + 37, my + 4); ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();
ctx.textAlign = "left";
ctx.fillText("v", cx + 48, my + 4);

// qvxB arrow along the rod, upward
ctx.strokeStyle = C.ink;
ctx.beginPath(); ctx.moveTo(cx - 22, my + 22); ctx.lineTo(cx - 22, my - 30); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx - 22, my - 30); ctx.lineTo(cx - 26, my - 23); ctx.lineTo(cx - 18, my - 23); ctx.closePath();
ctx.fillStyle = C.ink; ctx.fill();
ctx.textAlign = "right";
ctx.fillText("qvB", cx - 28, my - 8);

// field dots
ctx.fillStyle = C.faint;
for (let gy = top + 14; gy < bot; gy += 26) {
  ctx.beginPath(); ctx.arc(cx + 70, gy, 2, 0, Math.PI * 2); ctx.fill();
}
ctx.textAlign = "left";
ctx.fillText("B out of page", cx + 78, top + 14);

// divider
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(midX + 14, 20); ctx.lineTo(midX + 14, H - 20); ctx.stroke();

// ---- right panel: force balance on the rod ----
const rx = W * 0.76, ry = H * 0.50;
ctx.strokeStyle = C.accent; ctx.lineWidth = 5;
ctx.beginPath(); ctx.moveTo(rx, ry - 44); ctx.lineTo(rx, ry + 44); ctx.stroke();

function arrow(x0, y0, x1, y1, col, lab, side) {
  ctx.strokeStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  const dx = x1 - x0, dy = y1 - y0, n = Math.sqrt(dx * dx + dy * dy);
  const ux = dx / n, uy = dy / n;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * ux + 4 * uy, y1 - 7 * uy - 4 * ux);
  ctx.lineTo(x1 - 7 * ux - 4 * uy, y1 - 7 * uy + 4 * ux);
  ctx.closePath();
  ctx.fillStyle = col; ctx.fill();
  ctx.fillStyle = col;
  ctx.textAlign = side;
  ctx.fillText(lab, x1 + (side === "left" ? 5 : -5), y1 + 4);
}

arrow(rx, ry, rx + 62, ry, C.figure, "F applied", "left");
arrow(rx, ry, rx - 62, ry, C.ink, "B I L", "right");

ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("steady speed: the two balance", rx, H - 12);
ctx.fillText("charges pile up until the circuit carries them away", cx, 18);

const m = p.m, R = p.R, B = p.B, L = p.L, v0 = p.v0;
const k = B * B * L * L / R;
const tau = m / k;

const pad = 40;
const X0 = pad + 6, X1 = W - pad + 10;
const Y0 = H - 32, Y1 = 26;
const tMax = 5 * tau;
const X = s => X0 + (X1 - X0) * (s / tMax);
const Y = vv => Y0 - (Y0 - Y1) * (vv / v0);

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X0, Y0); ctx.lineTo(X1, Y0); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X0, Y0); ctx.lineTo(X0, Y1); ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("time (s)", (X0 + X1) / 2, H - 10);
ctx.textAlign = "left";
ctx.fillText("speed (m/s)", X0 + 4, Y1 - 8);
ctx.fillText(v0.toFixed(1), X0 - 34, Y1 + 4);
ctx.fillText("0", X0 - 16, Y0 + 4);
ctx.fillText(tMax.toFixed(2), X1 - 18, Y0 + 16);

// full decay curve
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 5]);
ctx.beginPath();
for (let i = 0; i <= 160; i++) {
  const s = tMax * i / 160;
  const vv = v0 * Math.exp(-s / tau);
  i === 0 ? ctx.moveTo(X(s), Y(vv)) : ctx.lineTo(X(s), Y(vv));
}
ctx.stroke();
ctx.setLineDash([]);

// swept so far
const now = t % (tMax + 1.0);
const cur = Math.min(now, tMax);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2.5;
ctx.beginPath();
for (let i = 0; i <= 160; i++) {
  const s = cur * i / 160;
  const vv = v0 * Math.exp(-s / tau);
  i === 0 ? ctx.moveTo(X(s), Y(vv)) : ctx.lineTo(X(s), Y(vv));
}
ctx.stroke();

const vnow = v0 * Math.exp(-cur / tau);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(cur), Y(vnow), 4.5, 0, Math.PI * 2); ctx.fill();

// tau marker
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(X(tau), Y0); ctx.lineTo(X(tau), Y(v0 * Math.exp(-1))); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.textAlign = "center";
ctx.fillText("one time constant", X(tau), Y(v0 * Math.exp(-1)) - 8);

const dist = v0 * tau;
const heat = 0.5 * m * v0 * v0;
out.note = "time constant " + tau.toFixed(3) + " s, total distance " + dist.toFixed(3) + " m, total heat " + heat.toFixed(3) + " J, speed now " + vnow.toFixed(2) + " m/s";

const B = p.B, L = p.L, w = p.w, R = p.R;
const emf = 0.5 * B * w * L * L;
const I = emf / R;

const cx = W * 0.5, cy = H * 0.52;
const rad = Math.min(W * 0.30, H * 0.36);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// circular rail
ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(cx, cy, rad, 0, Math.PI * 2); ctx.stroke();

// field dots
ctx.fillStyle = C.faint;
for (let gx = cx - rad; gx <= cx + rad; gx += 30) {
  for (let gy = cy - rad; gy <= cy + rad; gy += 30) {
    const dx = gx - cx, dy = gy - cy;
    if (dx * dx + dy * dy < rad * rad * 0.92) {
      ctx.beginPath(); ctx.arc(gx, gy, 1.8, 0, Math.PI * 2); ctx.fill();
    }
  }
}

// rotating rod
const ang = w * t * 0.06;
const ex = cx + rad * Math.cos(ang), ey = cy - rad * Math.sin(ang);
ctx.strokeStyle = C.accent; ctx.lineWidth = 4;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ex, ey); ctx.stroke();

// pivot
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 4, 0, Math.PI * 2); ctx.fill();

// a sample element dr at radius r, with its local speed arrow
const rr = rad * 0.62;
const px = cx + rr * Math.cos(ang), py = cy - rr * Math.sin(ang);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
const tx = -Math.sin(ang), ty = -Math.cos(ang);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px + 30 * tx, py + 30 * ty); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("speed w r", px + 30 * tx + 5, py + 30 * ty);

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("pivot", cx, cy + 18);
ctx.fillText("sliding contact", ex, ey - 10);
ctx.fillStyle = C.faint;
ctx.fillText("B out of page, along the axis", cx, H - 8);

out.note = "emf = half B w L squared = " + emf.toFixed(3) + " V, current " + I.toFixed(3) + " A";
